// The contract between the client store and the server. Types only.
//
// The client keeps its optimistic store. Every user action becomes a Command with a client-made
// opId (a uuid). The server applies it inside one transaction as app_user with the org already set,
// and the same opId sent twice changes nothing the second time. After commands settle, the client
// asks for a fresh Snapshot and replaces its state with it.
//
// Ids are uuid strings generated by the client (crypto.randomUUID) so an optimistic row and the
// stored row are the same row. Times are epoch milliseconds.

import type {
  CleanStatus,
  CleanTask,
  Dept,
  Hazard,
  HoldReason,
  Incident,
  Item,
  Request,
  Seq,
  Staff,
  WorkOrder,
} from "../domain/types";

export interface Snapshot {
  property: { id: string; name: string };
  properties: { id: string; name: string }[];
  staff: Staff[];
  requests: Request[];
  items: Record<string, Item>;
  wos: WorkOrder[];
  cleaning: CleanTask[];
  incidents: Incident[];
  /** Counters for the optimistic ticket numbers. `id` is unused and always 0. */
  seq: Seq;
  /** Server time when the snapshot was read. */
  at: number;
}

interface Base {
  opId: string;
}

export type Command =
  | (Base & {
      type: "logRequest";
      requestId: string;
      /** Ids for the items, in order. Presets first, then the bundle's parts. */
      itemIds: string[];
      room: string;
      presets?: string[];
      bundle?: string;
      remarks?: string;
      later?: boolean;
      vip?: boolean;
    })
  | (Base & { type: "completeRequest"; requestId: string; itemIds: string[]; presets: string[] })
  | (Base & { type: "relay" | "onSite" | "resume"; itemId: string })
  | (Base & { type: "hold"; itemId: string; reason: HoldReason })
  | (Base & { type: "finish"; itemId: string; status: "done" | "cant_do" | "duplicate" | "cancelled" })
  | (Base & { type: "transfer"; itemId: string; newItemId: string; dept: Dept })
  | (Base & { type: "escalate"; itemId: string; woId: string })
  | (Base & { type: "undoEscalate"; itemId: string })
  | (Base & {
      type: "assessWo";
      woId: string;
      assessment: string;
      assignType: "inhouse" | "outsource";
      contractor?: string;
      estCost: number;
    })
  | (Base & { type: "startWo" | "holdWo" | "reopenWo"; woId: string })
  | (Base & { type: "completeWo"; woId: string; actualCost: number })
  | (Base & { type: "cleanSet"; taskId: string; status: CleanStatus })
  | (Base & { type: "raiseSafety"; incidentId: string; room: string; text: string; hazard: Hazard })
  | (Base & { type: "downgradeIncident" | "resolveIncident"; incidentId: string })
  /** `at` is the time the call was made, as an ISO string from the device. */
  | (Base & { type: "record911"; incidentId: string; at: string });

export type CommandResult =
  | {
      ok: true;
      /** False when this opId had already been applied. Nothing changed. */
      applied: boolean;
      ticketNo?: number;
      woNo?: number;
      incidentNo?: number;
      /** raiseSafety: the report was merged into an existing active incident of the same hazard. */
      clusteredInto?: string;
    }
  | { ok: false; error: string };

export interface Ctx {
  orgId: string;
  propertyId: string;
  /** The staff row acting, or null when an owner or manager acts directly. */
  actorStaffId: string | null;
}
